import{_ as p,a0 as o,w as l,s as r,ao as g,I as n,x as s,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"科学音频处理（三）：如何使用 Octave 的高级数学技术处理音频文件 | LCTT x X-CMD","titleTemplate":false,"description":"科学音频处理（三）：如何使用 Octave 的高级数学技术处理音频文件 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"科学音频处理（三）：如何使用 Octave 的高级数学技术处理音频文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"科学音频处理（三）：如何使用 Octave 的高级数学技术处理音频文件 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160622 Part III - How to apply Advanced Mathematical Processing Effects on Audio files with Octave 4.0 on Ubuntu","title":"科学音频处理（三）：如何使用 Octave 的高级数学技术处理音频文件","tag":"201610","desc":""},"relativePath":"201610/20160622 Part III - How to apply Advanced Mathematical Processing Effects on Audio files with Octave 4.0 on Ubuntu.md","filePath":"[post].md"}'),d={name:"201610/20160622 Part III - How to apply Advanced Mathematical Processing Effects on Audio files with Octave 4.0 on Ubuntu.md"};function c(h,a,u,f,m,b){const t=o("Link");return l(),r("div",null,[a[13]||(a[13]=g(`<h1 id="科学音频处理-三-如何使用-octave-的高级数学技术处理音频文件" tabindex="-1">科学音频处理（三）：如何使用 Octave 的高级数学技术处理音频文件 <a class="header-anchor" href="#科学音频处理-三-如何使用-octave-的高级数学技术处理音频文件" aria-label="Permalink to “科学音频处理（三）：如何使用 Octave 的高级数学技术处理音频文件”">​</a></h1><p>我们的数字音频处理技术第三部分涵盖了信号调制内容，将解释如何进行调幅（Amplitude Modulation）、颤音效果（Tremolo Effect）和频率变化（Frequency Variation）。</p><h3 id="调制" tabindex="-1">调制 <a class="header-anchor" href="#调制" aria-label="Permalink to “调制”">​</a></h3><h4 id="调幅" tabindex="-1">调幅 <a class="header-anchor" href="#调幅" aria-label="Permalink to “调幅”">​</a></h4><p>正如它的名字暗示的那样， 影响正弦信号的振幅变化依据传递的信息而不断改变。正弦波因为承载着大量的信息被称作载波（carrier）。这种调制技术被用于许多的商业广播和市民信息传输波段（AM）。</p><h4 id="为何要使用调幅技术" tabindex="-1">为何要使用调幅技术？ <a class="header-anchor" href="#为何要使用调幅技术" aria-label="Permalink to “为何要使用调幅技术？”">​</a></h4><p><strong>调制发射</strong></p><p>假设信道是免费资源，有天线就可以发射和接收信号。这要求有效的电磁信号发射天线，它的大小和要被发射的信号的波长应该是同一数量级。很多信号，包括音频成分，通常在 100 赫兹或更低。对于这些信号，如果直接发射，我们就需要建立长达 300 公里的天线。如果通过信号调制将信息加载到 100MHz 的高频载波中，那么天线仅仅需要 1 米（横向长度）。</p><p><strong>集中调制与多通道</strong></p><p>假设多个信号占用一个通道，调制可以将不同的信号不同频域位置，以便接收者选择该特定信号。使用集中调制（“复用”）的应用有遥感探测数据、立体声调频收音机和长途电话等。</p><p><strong>克服设备限制的调制</strong></p><p>信号处理设备，比如过滤器、放大器，以及可以用它们简单组成的设备，它们的性能依赖于信号在频域中的境况以及高频率和低频信号的关系。调制可以用于传递信号到频域中的更容易满足设计需求的位置。调制也可以将“宽带信号“（高频和低频的比例很大的信号）转换成”窄带“信号。</p><p><strong>音频特效</strong></p><p>许多音频特效由于引人注目和处理信号的便捷性使用了调幅技术。我们可以说出很多，比如颤音、合唱、镶边等等。这种实用性就是我们关注它的原因。</p><h3 id="颤音效果" tabindex="-1">颤音效果 <a class="header-anchor" href="#颤音效果" aria-label="Permalink to “颤音效果”">​</a></h3><p>颤音效果是调幅最简单的应用，为实现这样的效果，我们会用周期信号改变（乘）音频信号，使用正弦或其他。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; tremolo=&#39;tremolo.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; fs=44100;</span></span>
<span class="line"><span>&gt;&gt; t=0:1/fs:10;</span></span>
<span class="line"><span>&gt;&gt; wo=2*pi*440*t;</span></span>
<span class="line"><span>&gt;&gt; wa=2*pi*1.2*t;</span></span>
<span class="line"><span>&gt;&gt; audiowrite(tremolo, cos(wa).*cos(wo),fs);</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremolo.png" alt="Tremolo"></p><p>这将创造一个正弦形状的信号，它的效果就像‘颤音’。</p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremoloshape.png" alt="Tremolo Shape"></p><h3 id="在真实音频文件中的颤音" tabindex="-1">在真实音频文件中的颤音 <a class="header-anchor" href="#在真实音频文件中的颤音" aria-label="Permalink to “在真实音频文件中的颤音”">​</a></h3><p>现在我们将展示真实世界中的颤音效果。首先，我们使用之前记录过男性发声 ‘A’ 的音频文件。这个信号图就像下面这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; [y,fs]=audioread(&#39;A.ogg&#39;);</span></span>
<span class="line"><span>&gt;&gt; plot(y);</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/avocalmale.png" alt="Vocal"></p><p>现在我们将创建一个完整的正弦信号，使用如下的参数：</p><ul><li>增幅 = 1</li><li>频率= 1.5Hz</li><li>相位 = 0</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; t=0:1/fs:4.99999999;</span></span>
<span class="line"><span>&gt;&gt; t=t(:);</span></span>
<span class="line"><span>&gt;&gt; w=2*pi*1.5*t;</span></span>
<span class="line"><span>&gt;&gt; q=cos(w);</span></span>
<span class="line"><span>&gt;&gt; plot(q);</span></span></code></pre></div><p>注意： 当我们创建一组时间值时，默认情况下，它是以列的格式呈现，如, 1x220500 的值。为了乘以这样的值，必须将其变成行的形式（220500x1）。这就是 <code>t=t(:)</code> 命令的作用。</p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/sinusoidal.png" alt="Sinusodial"></p><p>我们将创建第二份 ogg 音频格式的文件，它包含了如下的调制信号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; tremolo=&#39;tremolo.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; audiowrite(tremolo, q.*y,fs);</span></span></code></pre></div><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremsignal1.png" alt=""></p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/tremolsignal1.png" alt="Tremolo Signal"></p><h3 id="频率变化" tabindex="-1">频率变化 <a class="header-anchor" href="#频率变化" aria-label="Permalink to “频率变化”">​</a></h3><p>我们可以改变频率实现一些有趣的音效，比如原音变形，电影音效，多人比赛。</p><h4 id="正弦频率调制的影响" tabindex="-1">正弦频率调制的影响 <a class="header-anchor" href="#正弦频率调制的影响" aria-label="Permalink to “正弦频率调制的影响”">​</a></h4><p>这是正弦调制频率变化的演示代码，根据方程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Y=Ac*Cos(wo*Cos(wo/k))</span></span></code></pre></div><p>这里：</p><ul><li>Ac = 增幅</li><li>wo = 基频</li><li>k = 标量除数</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt; fm=&#39;fm.ogg&#39;;</span></span>
<span class="line"><span>&gt;&gt; fs=44100;</span></span>
<span class="line"><span>&gt;&gt; t=0:1/fs:10;</span></span>
<span class="line"><span>&gt;&gt; w=2*pi*442*t;</span></span>
<span class="line"><span>&gt;&gt; audiowrite(fm, cos(cos(w/1500).*w), fs);</span></span>
<span class="line"><span>&gt;&gt; [y,fs]=audioread(&#39;fm.ogg&#39;);</span></span>
<span class="line"><span>&gt;&gt; figure (); plot (y);</span></span></code></pre></div><p>信号图：</p><p><img src="https://www.howtoforge.com/images/ubuntu-octave-audio-processing-part-3/big/fmod.png" alt=""></p><p>你可以使用几乎任何类型的周期函数频率调制。本例中，我们仅仅用了一个正弦函数。请大胆的改变函数频率，用复合函数，甚至改变函数的类型。</p><hr>`,45)),n("p",null,[a[1]||(a[1]=s("via: ",-1)),e(t,{href:"https://www.howtoforge.com/tutorial/ubuntu-octave-audio-processing-part-3/"},{default:i(()=>[...a[0]||(a[0]=[s("https://www.howtoforge.com/tutorial/ubuntu-octave-audio-processing-part-3/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=s("作者：",-1)),e(t,{href:"https://www.howtoforge.com/tutorial/ubuntu-octave-audio-processing-part-3/"},{default:i(()=>[...a[2]||(a[2]=[s("David Duarte",-1)])]),_:1}),a[6]||(a[6]=s(" 译者：",-1)),e(t,{href:"https://github.com/theArcticOcean"},{default:i(()=>[...a[3]||(a[3]=[s("theArcticOcean",-1)])]),_:1}),a[7]||(a[7]=s(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[s("Linux中国",-1)])]),_:1}),a[12]||(a[12]=s(" 荣誉推出",-1))])])}const y=p(d,[["render",c]]);export{v as __pageData,y as default};
